    const bx = base[0] as number, by = base[1] as number;
    const w = s.qpos[3] as number, x = s.qpos[4] as number, y = s.qpos[5] as number, z = s.qpos[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const wx = s.qvel[0] as number, wy = s.qvel[1] as number;
    // Pelvis horizontal velocity in the heading frame, m/s.
    const vx = c * wx + sn * wy, vy = -sn * wx + c * wy;
    // Step toward the push: command the excess velocity beyond the operator's command.
    const ex = vx - bx, ey = vy - by;
    const dead = REFLEX_GAIN.dead;
    const gx = Math.abs(ex) > dead ? ex - Math.sign(ex) * dead : 0;
    const gy = Math.abs(ey) > dead ? ey - Math.sign(ey) * dead : 0;
    out[0] = bx + REFLEX_GAIN.k * gx;
    out[1] = by + REFLEX_GAIN.k * gy;
    out[2] = base[2] as number;
  }
}

/** Reflex gain k (ratio) and dead band (m/s) on the pelvis velocity error. */
export const REFLEX_GAIN = { k: 1.0, dead: 0.45 } as const;

/** Command limits the Walker applies after the reflex. */
export const REFLEX_LIMITS = { v: 1.0, yaw: 1.0 } as const;
